<template><section><div class="mb-6 flex items-end justify-between"><div><h1 class="text-2xl font-bold">{{t('analytics.title')}}</h1></div><div class="flex gap-1"> <button v-for="r in ranges" :key="r" class="btn-ghost text-xs" :class="range===r?'!bg-brand-500/15 !text-brand-300':''" @click="range=r">{{r}}</button></div></div><div class="grid gap-4 lg:grid-cols-2"><div class="card"><h2 class="mb-3 font-semibold">{{t('analytics.traffic')}}</h2><VChart class="h-[380px] w-full" :option="trafficOption" autoresize/></div><div class="card"><h2 class="mb-3 font-semibold">{{t('analytics.growth')}}</h2><VChart class="h-[380px] w-full" :option="growthOption" autoresize/></div></div></section></template>
<script setup lang="ts">import{ref,computed,watch}from'vue';import{useI18n}from'vue-i18n';import VChart from'vue-echarts';import{use}from'echarts/core';import{LineChart,BarChart}from'echarts/charts';import{GridComponent,TooltipComponent,LegendComponent}from'echarts/components';import{CanvasRenderer}from'echarts/renderers';import{api}from'../api/client';use([LineChart,BarChart,GridComponent,TooltipComponent,LegendComponent,CanvasRenderer]);const{t}=useI18n(),range=ref('7d'),points=ref<any[]>([]),growth=ref<any[]>([]),ranges=['24h','7d','30d','90d'];async function load(){const [a,b]=await Promise.all([api.get<any>(`/dashboard/analytics/${range.value}`),api.get<any>('/dashboard/growth')]);points.value=a.points||[];growth.value=b.points||[]}watch(range,load);const trafficOption=computed(()=>({tooltip:{trigger:'axis'},legend:{data:[t('traffic.upload'),t('traffic.download')]},xAxis:{type:'category',data:points.value.map(p=>p.bucket)},yAxis:{type:'value'},grid:{left:12,right:12,bottom:25,top:35,containLabel:true},series:[{name:t('traffic.upload'),type:'line',smooth:true,data:points.value.map(p=>Number(p.upload||0))},{name:t('traffic.download'),type:'line',smooth:true,data:points.value.map(p=>Number(p.download||0))}]}));const growthOption=computed(()=>({tooltip:{trigger:'axis'},xAxis:{type:'category',data:growth.value.map(p=>p.bucket)},yAxis:{type:'value'},grid:{left:12,right:12,bottom:25,top:20,containLabel:true},series:[{type:'bar',data:growth.value.map(p=>Number(p.value||0))}]}));load();</script>
